with j as (select * from jsonb_to_recordset($law7d0030$[{"code_id":"BK_RF","article_number":"57","version_date":"1998-07-31","article_text":"Неналоговые доходы бюджетов субъектов Российской Федерации формируются в соответствии со статьями 41,  42 и 46 настоящего Кодекса,  в том числе за счет:\n\nдоходов от использования имущества,  находящегося в государственной собственности субъектов Российской Федерации,  за исключением имущества бюджетных и автономных учреждений субъектов Российской Федерации,  а также имущества государственных унитарных предприятий субъектов Российской Федерации,  в том числе казенных,  - по нормативу 100 процентов;\n\nдоходов от продажи имущества (кроме акций и иных форм участия в капитале,  государственных запасов драгоценных металлов и драгоценных камней) ,  находящегося в государственной собственности субъектов Российской Федерации,  за исключением движимого имущества бюджетных и автономных учреждений субъектов Российской Федерации,  а также имущества государственных унитарных предприятий субъектов Российской Федерации,  в том числе казенных,  - по нормативу 100 процентов; (В редакции Федерального закона от 28.11.2018 № 457-ФЗ)\n\nдоходов от платных услуг,  оказываемых казенными учреждениями субъектов Российской Федерации;\n\nчасти прибыли унитарных предприятий,  созданных субъектами Российской Федерации,  остающейся после уплаты налогов и иных обязательных платежей в бюджет,  - в размерах,  определяемых в порядке,  установленном законами субъектов Российской Федерации;\n\nплаты за негативное воздействие на окружающую среду - по нормативу 40 процентов;\n\nплаты за использование лесов,  расположенных на землях лесного фонда,  в части,  превышающей минимальный размер арендной платы и минимальный размер платы по договору купли-продажи лесных насаждений,  платы по договору купли-продажи лесных насаждений для собственных нужд,  а также платы за использование лесов,  расположенных на землях иных категорий,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nдоходов от продажи земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  передачи в аренду таких земельных участков,  продажи прав на заключение договоров аренды таких земельных участков - по нормативу не более 50 процентов;\n\nдоходов от продажи объектов недвижимого имущества одновременно с занятыми такими объектами недвижимого имущества земельными участками,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не более 50 процентов;\n\nплаты за пользование водными объектами,  находящимися в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nразовых платежей за пользование недрами при наступлении определенных событий,  оговоренных в лицензии,  по участкам недр,  содержащих месторождения природных алмазов,  - по нормативу 100 процентов;\n\nрегулярных платежей за пользование недрами при пользовании недрами на территории Российской Федерации - по нормативу 60 процентов;\n\nразовых платежей за пользование недрами при наступлении определенных событий,  оговоренных в лицензии,  при пользовании недрами на территории Российской Федерации по участкам недр местного значения - по нормативу 100 процентов;\n\nплаты от продажи на аукционе права на заключение договора пользования водными биологическими ресурсами,  находящимися в собственности субъекта Российской Федерации,  - по нормативу 100 процентов;\n\nплаты за заключение договора пользования рыболовным участком,  состоящим из акватории водного объекта,  находящегося в собственности субъекта Российской Федерации,  или ее части,  - по нормативу 100 процентов; (В редакции  федеральных законов от 01.07.2021 № 251-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nплаты за предоставление государственными органами субъектов Российской Федерации,  казенными учреждениями субъектов Российской Федерации сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  - по нормативу 100 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  - по нормативу 50 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае подачи заявления о предоставлении сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  в электронной форме и выдачи указанных документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 25 процентов;\n\nсборов за участие в конкурсе (аукционе)  на право пользования участками недр местного значения - по нормативу 100 процентов;\n\nплаты за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nплаты по соглашениям об установлении сервитута,  заключенным исполнительными\n\nный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию средства массовой информации,  за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации) ,  продукция которого предназначена для распространения преимущественно на территории субъекта Российской Федерации,  территории муниципального образования,  - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию средства массовой информации,  за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации) ,  продукция которого предназначена для распространения преимущественно на всей территории Российской Федерации,  за ее пределами,  на территориях двух и более субъектов Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.12.2017 № 434-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 27.12.2009 № 374-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за действия исполнительных органов субъектов Российской Федерации,  связанные с лицензированием образовательной деятельности,  осуществляемым в пределах переданных полномочий Российской Федерации в области образования,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 08.11.2010 № 293-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за действия исполнительных органов субъектов Российской Федерации,  связанные с осуществляемой в пределах переданных полномочий Российской Федерации в области образования государственной аккредитацией образовательной деятельности,  - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 08.11.2010 № 293-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины (подлежащей зачислению по месту государственной регистрации,  совершения юридически значимых действий или выдачи документов)  за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 50 процентов; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nгосударственной пошлины (подлежащей зачислению по месту государственной регистрации,  совершения юридически значимых действий или выдачи документов)  за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в электронной форме и выдачи документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 25 процентов; (Дополнение абзацем - Федеральный закон от 07.03.2018 № 45-ФЗ)\n\nналога на профессиональный доход - по нормативу 63 процента; (Дополнение абзацем - Федеральный закон от 27.11.2018 № 423-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 27.12.2018 № 504-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)  (Утратил силу  - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на добычу полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  - по нормативу 17 процентов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nналога на добычу полезных ископаемых в виде угля коксующегося - по нормативу 30 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде железной руды (за исключением окисленных железистых кварцитов)  - по нормативу 17 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд - по нормативу 17 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде,  - по нормативу 17 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nакциза на сталь жидкую - по нормативу 17 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога,  взимаемого в связи с применением специального налогового режима \"Автоматизированная упрощенная система налогообложения\",  в том числе минимального налога,  - по нормативу 54 процента; (Дополнение абзацем - Федеральный закон от 25.02.2022 № 22-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей и составляющей не более 5 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце шестьдесят седьмом настоящего пункта) ,  - по нормативу 74 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 702 тысячи рублей,  относящейся к части налоговой базы,  превышающей 5 миллионов рублей и составляющей не более 20 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце шестьдесят седьмом настоящего пункта) ,  - по нормативу 61 процент; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце шестьдесят седьмом настоящего пункта) ,  - по нормативу 55 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце шестьдесят седьмом настоящего пункта) ,  - по нормативу 51 процент; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом статьи 50 настоящего Кодекса) ,  а также налога на доходы физических лиц в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 74 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  а также налога на доходы физических лиц в части суммы налога,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце шестьдесят девятом настоящего пункта) ,  - по нормативу 85 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 74 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на природный газ,  полученный для производства аммиака,  - по нормативу 17 процентов. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Пункт в редакции Федерального закона от 08.11.2007 № 257-ФЗ)\n\n21. В текущем финансовом году налоговые доходы от акцизов на автомобильный бензин,  прямогонный бензин,  дизельное топливо,  моторные масла для дизельных и (или)  карбюраторных (инжекторных)  двигателей,  подлежащие зачислению в бюджеты субъектов Российской Федерации в соответствии с нормативом,  установленным настоящей статьей,  распределяются Федеральным казначейством в соответствии с нормативами,  установленными федеральным законом о федеральном бюджете на текущий финансовый год,  с учетом установленных законами субъектов Российской Федерации дифференцированных нормативов отчислений в местные бюджеты. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\n22. В текущем финансовом году налоговые доходы от акцизов на алкогольную продукцию с объемной долей этилового спирта свыше 9 процентов,  за исключением пива,  вин (кроме крепленого (ликерного)  вина) ,  вин наливом,  плодовой алкогольной продукции,  игристых вин,  включая российское шампанское,  а также за исключением виноградосодержащих напитков,  плодовых алкогольных напитков,  изготавливаемых без добавления ректификованного этилового спирта,  произведенного из пищевого сырья,  и (или)  без добавления спиртованных виноградного или иного плодового сусла,  и (или)  без добавления дистиллятов,  и (или)  без добавления крепленого (ликерного)  вина,  подлежащие зачислению в бюджеты субъектов Российской Федерации в соответствии с нормативом,  установленным настоящей статьей,  распределяются Федеральным казначейством между бюджетами субъектов Российской Федерации в соответствии с федеральным законом о федеральном бюджете. (Дополнение пунктом - Федеральный закон от 30.11.2016 № 409-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\n23. В текущем финансовом году налоговые доходы от акцизов на спирт этиловый из пищевого или непищевого сырья,  акцизов на спиртосодержащую продукцию,  подлежащие зачислению в бюджеты субъектов Российской Федерации в соответствии с нормативом,  установленным настоящей статьей,  в размере 50 процентов объема указанных доходов распределяются Федеральным казначейством между бюджетами субъектов Российской Федерации в соответствии с федеральным законом о федеральном бюджете. (Дополнение пунктом - Федеральный закон от 15.04.2019 № 62-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\n24. (Дополнение пунктом - Федеральный закон от 31.07.2020 № 263-ФЗ)  (Утратил силу - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\n3. В бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя подлежат зачислению налоговые доходы от федеральных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами,  подлежащих в соответствии с настоящим Кодексом зачислению в местные бюджеты и бюджеты субъектов Российской Федерации,  а также доходы от торгового сбора,  подлежащего уплате на территориях этих субъектов Российской Федерации. (В редакции федеральных законов от 22.10.2014 № 311-ФЗ; от 03.11.2015 № 301-ФЗ)\n\n4. Налоговые доходы от региональных налогов,  установленных органами государственной власти края (области) ,  в состав которого входит автономный округ,  подлежат зачислению в бюджет края (области) . Налоговые доходы от региональных налогов,  установленных органами государственной власти автономного округа,  подлежат зачислению в бюджет автономного округа.\n\nЕсли иное не установлено федеральным законом о федеральном бюджете и договором между органами государственной власти края (области) ,  в состав которого входит автономный округ,  и органами государственной власти соответствующего автономного округа,  налоговые доходы,  указанные в пункте 2 настоящей статьи,  подлежат зачислению в бюджет края (области) ,  за исключением налога на доходы физических лиц по нормативу 15 процентов,  подлежащего зачислению в бюджет автономного округа,  передаваемого в полном объеме органами государственной власти автономного округа в соответствующие местные бюджеты в порядке,  предусмотренном статьей 58 настоящего Кодекса. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n5. Указанные в настоящей статье налоговые доходы могут быть переданы полностью или частично органами государственной власти субъектов Российской Федерации в соответствующие местные бюджеты в порядке,  предусмотренном статьей 58 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 57. Неналоговые доходы бюджетов субъектов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03baba204777ddd39850755e2c5385f493e4e32c52cff5979d32b878a13355e8"}]$law7d0030$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
